// Build a minimal-but-complete memory manager using standard libc to validate the test harness.
UriMemoryManager backend;
auto b_malloc = +[](UriMemoryManager *, size_t n) -> void * { return ::malloc(n); };
auto b_free = +[](UriMemoryManager *, void *p) -> void { ::free(p); };
auto b_realloc = +[](UriMemoryManager *, void *p, size_t n) -> void * { return ::realloc(p, n); };
auto b_calloc = +[](UriMemoryManager *, size_t nmemb, size_t size) -> void * {
    size_t total = nmemb * size;
    if (nmemb != 0 && total / nmemb != size) { return nullptr; }
    void *q = (total == 0) ? nullptr : ::malloc(total);
    if (q) { std::memset(q, 0, total); }
    return q;
};
auto b_reallocarray = +[](UriMemoryManager *, void *p, size_t nmemb, size_t size) -> void * {
    size_t total = nmemb * size;
    if (nmemb != 0 && total / nmemb != size) { return nullptr; }
    return ::realloc(p, total);
};
backend.malloc = b_malloc;
backend.calloc = b_calloc;
backend.realloc = b_realloc;
backend.reallocarray = b_reallocarray;
