import random
import ipaddress

# Generator for IPv4 address text buffers suitable for various stubs expecting
# [first, afterLast) slices or whole strings. We try to produce valid IPv4
# representations in a variety of interesting, yet valid forms, mixed with
# surrounding noise to exercise substring picking in fuzzers.

UNRESERVED = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"
DELIMS = "!$&'()*+,;=:@"
WS = " \t"

def _rand(rs: random.Random, lo: int, hi: int) -> int:
    return rs.randrange(lo, hi+1)

def _ipv4_dec_octet(rs: random.Random) -> str:
    # Generate a 0..255 decimal without leading zeros except for zero itself
    v = rs.randrange(0, 256)
    return str(v)

def _ipv4_with_leading_zeros(rs: random.Random) -> str:
    # Still valid in many parsers only when strictly dotted-decimal without octal semantics.
    # To stay valid per strict RFC 3986 host IPv4 dotted-decimal, avoid leading zeros except zero.
    # We therefore only occasionally pad single zero octet.
    if rs.random() < 0.2:
        return "0"
    return _ipv4_dec_octet(rs)

def _gen_ipv4_plain(rs: random.Random) -> str:
    # Standard dotted-decimal
    octets = [_ipv4_dec_octet(rs) for _ in range(4)]
    return ".".join(octets)

def _gen_ipv4_edge(rs: random.Random) -> str:
    # Edge values 0 and 255 included
    choices = [0, 1, 254, 255]
    octets = [str(rs.choice(choices)) for _ in range(4)]
    return ".".join(octets)

def _gen_ipv4_mixed_lengths(rs: random.Random) -> str:
    # Mix 1-3 digit decimal, still valid
    parts = []
    for _ in range(4):
        v = rs.randrange(0, 256)
        # Occasionally add leading zeros only for zero to stay valid unambiguously
        if v == 0 and rs.random() < 0.5:
            parts.append("0")
        else:
            parts.append(str(v))
    return ".".join(parts)

def _surround_noise(rs: random.Random, core: str) -> bytes:
    # Create a buffer that contains the IPv4 core possibly surrounded by noise
    # Fuzzer stubs often pick arbitrary [first, afterLast) from this buffer.
    # We keep buffer size reasonable (< 1024) and ASCII-safe.
    left_noise_types = ["none", "ws", "text", "junk", "scheme", "bracket"]
    right_noise_types = left_noise_types

    def mk_noise(kind: str) -> str:
        if kind == "none":
            return ""
        if kind == "ws":
            return "".join(rs.choice(WS) for _ in range(_rand(rs, 0, 4)))
        if kind == "text":
            n = _rand(rs, 0, 16)
            return "".join(rs.choice(UNRESERVED) for _ in range(n))
        if kind == "junk":
            n = _rand(rs, 0, 16)
            alphabet = UNRESERVED + DELIMS + WS + "[]{}<>#?/%"
            return "".join(rs.choice(alphabet) for _ in range(n))
        if kind == "scheme":
            schemes = ["http://", "https://", "ftp://", "file://", "ssh://"]
            return rs.choice(schemes)
        if kind == "bracket":
            # Put IPv4 inside brackets occasionally to simulate text contexts
            return "["
        return ""

    lkind = rs.choice(left_noise_types)
    rkind = rs.choice(right_noise_types)

    left = mk_noise(lkind)
    right = mk_noise(rkind)

    # If we opened a bracket, try to close it after the core
    if left.endswith("[") and not right.startswith("]"):
        right = "]" + right

    s = (left + core + right)
    # Ensure non-empty buffer; stubs may handle empty but we want valid slices available
    if not s:
        s = core
    # Bound total size to 1024 for safety
    if len(s) > 1024:
        s = s[:1024]
    return s.encode('ascii', 'ignore')

def _gen_core_ipv4(rs: random.Random) -> str:
    mode = rs.random()
    if mode < 0.34:
        return _gen_ipv4_plain(rs)
    elif mode < 0.67:
        return _gen_ipv4_edge(rs)
    else:
        return _gen_ipv4_mixed_lengths(rs)

def generate(seed: int) -> bytes:
    rs = random.Random(seed)
    # Decide whether to return only the IPv4 or with surrounding noise
    core = _gen_core_ipv4(rs)

    # Occasionally include IPv4 as the whole buffer (good for stubs that use full string)
    if rs.random() < 0.4:
        return core.encode('ascii')

    # Otherwise, surround with noise so substring selection can still find a valid IPv4 span
    return _surround_noise(rs, core)

import random
import ipaddress
from typing import List

# Generate interesting, valid IPv6 address texts per RFC 4291/5952, including
# compressed, full, IPv4-embedded, scoped (zone id), and with varied hex casing.
# The fuzz stubs will pass the returned bytes as a [first, afterLast) ANSI range.
# Ensure size <= 1024 in stubs; we keep <= 512 here.

HEX_LOWER = "0123456789abcdef"
HEX_UPPER = "0123456789ABCDEF"


def _rand(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def _hexdigits(rng: random.Random, count: int, upper: bool) -> str:
    alphabet = HEX_UPPER if upper else HEX_LOWER
    return ''.join(rng.choice(alphabet) for _ in range(count))


def _ipv4_text(rng: random.Random) -> str:
    # Generate a valid dotted-quad, with edge cases
    choices: List[int] = []
    for i in range(4):
        mode = _rand(rng, 0, 4)
        if mode == 0:
            v = 0
        elif mode == 1:
            v = 255
        elif mode == 2:
            v = _rand(rng, 1, 254)
        elif mode == 3:
            # prefer typical private ranges
            v = rng.choice([10, 172, 192, _rand(rng, 1, 254)])
        else:
            v = _rand(rng, 0, 255)
        choices.append(v)
    return f"{choices[0]}.{choices[1]}.{choices[2]}.{choices[3]}"


def _expand_ipv6_groups(addr: ipaddress.IPv6Address) -> List[int]:
    # Return the 8 16-bit groups
    n = int(addr)
    groups = []
    for i in range(8):
        shift = (7 - i) * 16
        groups.append((n >> shift) & 0xFFFF)
    return groups


def _format_group(val: int, rng: random.Random) -> str:
    # 1 to 4 hex digits, optional upper/lower, optional leading zeros
    upper = _maybe(rng, 0.5)
    # Minimal form (no leading zeros) or keep some leading zeros
    h = f"{val:x}" if not upper else f"{val:X}"
    if val == 0:
        # sometimes show explicit 0, sometimes 00/000/0000
        if _maybe(rng, 0.5):
            return h
        width = _rand(rng, 1, 4)
        return (HEX_UPPER if upper else HEX_LOWER)[0] * 0 + ("0" * width)
    if _maybe(rng, 0.4):
        # add leading zeros up to width 4
        width = _rand(rng, max(1, len(h)), 4)
        fmt = f"%0{width}{'X' if upper else 'x'}"
        return fmt % val
    return h


def _compress_groups(groups: List[int], rng: random.Random) -> str:
    # Choose a longest run of zeros to compress, or maybe none
    runs = []
    start = None
    for i, g in enumerate(groups):
        if g == 0 and start is None:
            start = i
        if g != 0 and start is not None:
            runs.append((start, i - 1))
            start = None
    if start is not None:
        runs.append((start, 7))
    best = None
    if runs:
        best = max(runs, key=lambda t: (t[1] - t[0] + 1))
    # maybe do not compress
    if not best or _maybe(rng, 0.3) or (best[1] - best[0] + 1) < 2:
        # no compression; format all groups
        return ':'.join(_format_group(g, rng) for g in groups)
    i, j = best
    left = groups[:i]
    right = groups[j + 1:]
    left_txt = ':'.join(_format_group(g, rng) for g in left)
    right_txt = ':'.join(_format_group(g, rng) for g in right)
    if left_txt and right_txt:
        return left_txt + '::' + right_txt
    elif left_txt:
        return left_txt + '::'
    elif right_txt:
        return '::' + right_txt
    else:
        return '::'


def _with_zone(addr_txt: str, rng: random.Random) -> str:
    # Optionally append a zone id (scope), e.g., %eth0 or %25eth0
    if not _maybe(rng, 0.25):
        return addr_txt
    zone_alnums = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    # simple zones like eth0, en0, lo, or numeric
    base = rng.choice(['eth', 'en', 'wlan', 'lo', '']) + (str(_rand(rng, 0, 9)) if _maybe(rng, 0.7) else '')
    if base == '':
        base = ''.join(rng.choice(zone_alnums) for _ in range(_rand(rng, 1, 4)))
    zone = base
    # Per RFC 6874, zone in URIs must be percent-encoded as %25, but our targets
    # parse raw IPv6 text without brackets for uriparser internal helpers; still, include both forms.
    if _maybe(rng, 0.5):
        return addr_txt + '%' + zone
    else:
        return addr_txt + '%25' + zone


def _embed_ipv4(groups: List[int], rng: random.Random) -> str:
    # Embed an IPv4 dotted-quad in the last two groups, with possible compression
    g6 = groups.copy()
    # ensure last two groups match IPv4 parts
    a = _rand(rng, 0, 255)
    b = _rand(rng, 0, 255)
    c = _rand(rng, 0, 255)
    d = _rand(rng, 0, 255)
    g6[6] = (a << 8) | b
    g6[7] = (c << 8) | d
    core = _compress_groups(g6[:6] + [g6[6], g6[7]], rng)
    # Replace the textual tail after the last colon with dotted quad if not fully compressed to nothing
    # Safer approach: rebuild text with IPv4 at the end
    text_head = _compress_groups(g6[:6], rng)
    if text_head == '::':
        base = '::'
    elif text_head == '':
        base = ''
    else:
        base = text_head + ':'
    return base + _ipv4_text(random.Random(rng.getstate()[1][0] ^ 0xA53))


def _random_ipv6_text(rng: random.Random) -> str:
    # Start from a random 128-bit address
    addr = ipaddress.IPv6Address(rng.getrandbits(128))
    groups = _expand_ipv6_groups(addr)

    # Occasionally craft special ranges to hit more code paths
    special = _rand(rng, 0, 7)
    if special == 0:
        # Unspecified
        groups = [0] * 8
    elif special == 1:
        # Loopback
        groups = [0] * 7 + [1]
    elif special == 2:
        # Link-local fe80::/64 with some iid
        groups[0] = 0xFE80
        for i in range(1, 4):
            groups[i] = 0
    elif special == 3:
        # 2001:db8:: documentation prefix
        groups[0] = 0x2001
        groups[1] = 0x0DB8
    # else: leave random

    # Possibly produce IPv4-embedded form
    if _maybe(rng, 0.25):
        txt = _embed_ipv4(groups, rng)
    else:
        txt = _compress_groups(groups, rng)

    # Randomize hex case globally by flipping some letters
    if _maybe(rng, 0.3):
        # toggle case randomly per letter A-F/a-f
        new_chars = []
        for ch in txt:
            if ch in 'abcdef' and _maybe(rng, 0.5):
                new_chars.append(ch.upper())
            elif ch in 'ABCDEF' and _maybe(rng, 0.5):
                new_chars.append(ch.lower())
            else:
                new_chars.append(ch)
        txt = ''.join(new_chars)

    # Optional zone id
    txt = _with_zone(txt, rng)

    return txt


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose one of several IPv6 generation strategies
    strategy = _rand(rng, 0, 7)
    candidates: List[str] = []

    if strategy == 0:
        # simple full form 8 groups
        groups = [_rand(rng, 0, 0xFFFF) for _ in range(8)]
        s = ':'.join(f"{g:x}" if _maybe(rng, 0.5) else f"{g:X}" for g in groups)
        candidates.append(s)
    elif strategy == 1:
        # heavily compressed zero runs
        candidates.append(_random_ipv6_text(rng))
    elif strategy == 2:
        # IPv4-embedded frequently
        groups = [_rand(rng, 0, 0xFFFF) for _ in range(8)]
        candidates.append(_embed_ipv4(groups, rng))
    elif strategy == 3:
        # edge literals
        candidates.extend(["::", "::1", "2001:db8::", "fe80::" + _hexdigits(rng, _rand(rng, 1, 4), _maybe(rng, 0.5))])
    elif strategy == 4:
        # Include scoped variants
        base = _random_ipv6_text(rng)
        if '%' not in base:
            candidates.append(_with_zone(base, rng))
        else:
            candidates.append(base)
    elif strategy == 5:
        # Many random valid addresses
        for _ in range(3):
            candidates.append(_random_ipv6_text(rng))
    elif strategy == 6:
        # Max groups with varied leading zeros
        groups = [_rand(rng, 0, 0xFFFF) for _ in range(8)]
        formatted = []
        for g in groups:
            width = _rand(rng, 1, 4)
            formatted.append(("%0" + str(width) + ("X" if _maybe(rng, 0.5) else "x")) % g)
        candidates.append(':'.join(formatted))
    else:
        # Mixed list including documentation and private ranges
        candidates.extend([
            "2001:db8::1",
            "2001:db8:85a3::8a2e:370:7334",
            "fe80::1%eth0",
            "fe80::1%25eth0",
            "::ffff:" + _ipv4_text(rng),
        ])

    # Pick a candidate and ensure length bounds
    s = rng.choice(candidates)
    if len(s) > 512:
        s = s[:512]
    # Return as bytes (ANSI)
    return s.encode('ascii', errors='strict')

import random
import string
from typing import List, Tuple

# Generator for wide-char URI inputs, but returns bytes; harness maps bytes->wchar_t by (unsigned char) value.
# Goal: produce valid URIs and file: URIs suitable for various parsers and filename converters.

SCHEMES = [
    "http", "https", "ftp", "file", "ws", "wss", "mailto", "urn", "tel", "ldap"
]

UNRESERVED = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
PCHARS = UNRESERVED + SUBDELIMS + ":@"
HEX = "0123456789ABCDEF"


def pct_encode_byte(b: int) -> str:
    return "%" + HEX[(b >> 4) & 0xF] + HEX[b & 0xF]


def rand_pct_encoded(rng: random.Random) -> str:
    # percent-encode random byte in range 1..255 (avoid 0)
    b = rng.randint(1, 255)
    return pct_encode_byte(b)


def rand_label(rng: random.Random, min_len=1, max_len=10) -> str:
    # Registered name label (RFC 3986, LDH labels plus pct-enc)
    n = rng.randint(min_len, max_len)
    label = []
    for i in range(n):
        choice = rng.random()
        if choice < 0.82:
            ch = rng.choice(string.ascii_lowercase + string.ascii_uppercase + string.digits + "-")
            label.append(ch)
        elif choice < 0.90:
            label.append(rand_pct_encoded(rng))
        else:
            label.append(rng.choice("_~"))
    # avoid leading/trailing hyphen in DNS-looking labels sometimes
    if label and label[0] == "-":
        label[0] = "a"
    if label and label[-1] == "-":
        label[-1] = "b"
    return "".join(label)


def rand_reg_name_host(rng: random.Random) -> str:
    # Compose 1-4 labels
    parts = [rand_label(rng) for _ in range(rng.randint(1, 4))]
    return ".".join(parts)


def rand_ipv4(rng: random.Random) -> str:
    # Generate common and edge IPv4 forms
    if rng.random() < 0.2:
        # include leading zeros on some octets
        return ".".join(f"{rng.randint(0,255):03d}" for _ in range(4))
    return ".".join(str(rng.randint(0, 255)) for _ in range(4))


def rand_ipv6(rng: random.Random) -> str:
    # Build a valid IPv6, including compressed forms
    hextet = lambda: f"{rng.randint(0, 0xFFFF):x}"
    if rng.random() < 0.5:
        # full 8 hextets
        return ":".join(hextet() for _ in range(8))
    # compressed
    left = [hextet() for _ in range(rng.randint(0, 7))]
    right = [hextet() for _ in range(rng.randint(0, 7 - len(left)))]
    return (":".join(left) + ("::" if left or right else "::") + ":".join(right))


def rand_ipvfuture(rng: random.Random) -> str:
    # v<HEXDIG>.<address-literal>
    ver = rng.choice("0123456789ABCDEF")
    tail_chars = UNRESERVED + SUBDELIMS + ":"
    tail = []
    for _ in range(rng.randint(1, 12)):
        if rng.random() < 0.12:
            tail.append(rand_pct_encoded(rng))
        else:
            tail.append(rng.choice(tail_chars))
    return "v" + ver + "." + "".join(tail)


def rand_userinfo(rng: random.Random) -> str:
    s = []
    for _ in range(rng.randint(1, 12)):
        p = rng.random()
        if p < 0.82:
            s.append(rng.choice(UNRESERVED + SUBDELIMS + ":"))
        elif p < 0.94:
            s.append(rand_pct_encoded(rng))
        else:
            s.append(" ")  # will be acceptable in query/fragment but here percent-encode sometimes
    # percent-encode spaces to keep it well-formed
    return "".join(ch if ch != " " else "%20" for ch in s)


def rand_port(rng: random.Random) -> str:
    if rng.random() < 0.3:
        return str(rng.randint(0, 65535))
    # leading zeros variant (still digits)
    return ("0" * rng.randint(1, 3)) + str(rng.randint(0, 65535))


def rand_path_segment(rng: random.Random) -> str:
    seg = []
    for _ in range(rng.randint(0, 10)):
        p = rng.random()
        if p < 0.8:
            seg.append(rng.choice(PCHARS))
        elif p < 0.92:
            seg.append(rand_pct_encoded(rng))
        else:
            seg.append(rng.choice(["@", ".", "_", "-"]))
    return "".join(seg)


def rand_path(rng: random.Random, absolute: bool) -> str:
    # Build path-abempty or path-absolute
    segs = [rand_path_segment(rng) for _ in range(rng.randint(0, 5))]
    core = "/".join(segs)
    return ("/" + core) if absolute else core


def rand_query(rng: random.Random) -> str:
    # Compose k=v pairs, allow plus and percent encodings
    parts = []
    pairs = rng.randint(0, 4)
    for _ in range(pairs):
        k = rand_label(rng, 1, 8)
        v = rand_label(rng, 0, 10)
        parts.append(f"{k}={v}")
    base = "&".join(parts)
    # randomly add extra pchars and percent encodings
    extra = []
    for _ in range(rng.randint(0, 6)):
        if rng.random() < 0.65:
            extra.append(rng.choice(PCHARS + "/?"))
        else:
            extra.append(rand_pct_encoded(rng))
    if extra:
        if base:
            base += "&" + "".join(extra)
        else:
            base = "".join(extra)
    return base


def rand_fragment(rng: random.Random) -> str:
    frag = []
    for _ in range(rng.randint(0, 12)):
        if rng.random() < 0.7:
            frag.append(rng.choice(PCHARS + "/?"))
        else:
            frag.append(rand_pct_encoded(rng))
    return "".join(frag)


def build_authority(rng: random.Random) -> Tuple[str, bool]:
    # Returns authority string and whether host present
    userinfo = ""
    if rng.random() < 0.4:
        userinfo = rand_userinfo(rng) + "@"
    # Choose host kind
    kind = rng.random()
    if kind < 0.4:
        host = rand_reg_name_host(rng)
    elif kind < 0.7:
        host = rand_ipv4(rng)
    elif kind < 0.95:
        host = "[" + rand_ipv6(rng) + "]"
    else:
        host = "[" + rand_ipvfuture(rng) + "]"
    port = ":" + rand_port(rng) if rng.random() < 0.5 else ""
    return userinfo + host + port, True


def build_absolute_hier_uri(rng: random.Random) -> str:
    scheme = rng.choice(SCHEMES)
    # For file scheme, sometimes include authority as host, sometimes none
    if scheme == "file":
        if rng.random() < 0.6:
            auth, _ = build_authority(rng)
            authority = "//" + auth
            path = rand_path(rng, absolute=True)
        else:
            authority = ""
            # path-absolute required without authority
            path = rand_path(rng, absolute=True)
    else:
        authority = "//" + build_authority(rng)[0] if rng.random() < 0.9 else ""
        absolute = authority != ""
        path = rand_path(rng, absolute=absolute)
    query = ("?" + rand_query(rng)) if rng.random() < 0.6 else ""
    fragment = ("#" + rand_fragment(rng)) if rng.random() < 0.3 else ""
    return f"{scheme}:{authority}{path}{query}{fragment}"


def build_relative_ref(rng: random.Random) -> str:
    # Relative reference, possibly with authority
    with_auth = rng.random() < 0.4
    authority = "//" + build_authority(rng)[0] if with_auth else ""
    path = rand_path(rng, absolute=with_auth or rng.random() < 0.5)
    query = ("?" + rand_query(rng)) if rng.random() < 0.6 else ""
    fragment = ("#" + rand_fragment(rng)) if rng.random() < 0.3 else ""
    return f"{authority}{path}{query}{fragment}"


def build_mailto(rng: random.Random) -> str:
    # mailto:local@domain[?headers]
    local = rand_label(rng, 1, 10)
    domain = rand_reg_name_host(rng)
    headers = ""
    if rng.random() < 0.5:
        # e.g., subject=...&body=...
        q = []
        if rng.random() < 0.8:
            q.append("subject=" + rand_label(rng, 1, 12))
        if rng.random() < 0.6:
            q.append("body=" + rand_label(rng, 1, 20))
        if q:
            headers = "?" + "&".join(q)
    return f"mailto:{local}@{domain}{headers}"


def build_urn(rng: random.Random) -> str:
    nid = rng.choice(["isbn", "uuid", "example", "ietf"])
    nss = []
    for _ in range(rng.randint(3, 10)):
        if rng.random() < 0.85:
            nss.append(rng.choice(UNRESERVED + SUBDELIMS + ":"))
        else:
            nss.append(rand_pct_encoded(rng))
    return "urn:" + nid + ":" + "".join(nss)


def build_windows_file_uri(rng: random.Random) -> str:
    # file:///C:/path with percent-enc spaces etc.; good for uriUriStringToWindowsFilenameW
    drive = rng.choice(string.ascii_letters[:6]).upper()
    segs = []
    for _ in range(rng.randint(1, 4)):
        s = rand_path_segment(rng)
        # introduce spaces percent-encoded
        if rng.random() < 0.5:
            s += "%20"
        segs.append(s)
    path = "/".join([drive + ":"] + segs)
    return "file:///" + path


def build_unix_file_uri(rng: random.Random) -> str:
    # file:///absolute/unix/path
    segs = []
    for _ in range(rng.randint(1, 5)):
        s = rand_path_segment(rng)
        if rng.random() < 0.4:
            s += "%20"
        segs.append(s)
    return "file:///" + "/".join(segs)


def pick_uri(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.22:
        return build_absolute_hier_uri(rng)
    if choice < 0.37:
        return build_relative_ref(rng)
    if choice < 0.50:
        return build_windows_file_uri(rng)
    if choice < 0.63:
        return build_unix_file_uri(rng)
    if choice < 0.77:
        return build_mailto(rng)
    if choice < 0.90:
        return build_urn(rng)
    # Direct host-only URI with scheme and authority
    scheme = rng.choice(["http", "https", "ftp"]) 
    host_kind = rng.random()
    if host_kind < 0.4:
        host = rand_reg_name_host(rng)
    elif host_kind < 0.7:
        host = rand_ipv4(rng)
    else:
        host = "[" + rand_ipv6(rng) + "]"
    return f"{scheme}://{host}"


def to_bytes_as_wide(u: str) -> bytes:
    # Harness maps each byte to wchar_t by static_cast<unsigned char>, so we deliver bytes of codepoints (0..255)
    # We need to map ASCII chars directly and percent sequences as ASCII too.
    # Ensure size <= 1024 as harness truncates; we keep below and limit overall buffer <= 4096.
    b = u.encode('latin-1', errors='ignore')
    if len(b) == 0:
        b = b"/"  # minimal non-empty
    if len(b) > 1024:
        b = b[:1024]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build multiple URIs sometimes to exercise range-based parsing (without NUL) and zero-terminated ones
    # However, harness consumes a single buffer; provide one URI per call.
    uri = pick_uri(rng)
    # Occasionally append query/fragment variations to diversify
    if rng.random() < 0.3 and '?' not in uri and uri.startswith(('http:', 'https:', 'ftp:', 'file:')):
        uri += '?' + rand_query(rng)
    if rng.random() < 0.25 and '#' not in uri:
        uri += '#' + rand_fragment(rng)
    return to_bytes_as_wide(uri)

import random
import string
from typing import List, Tuple

# Generator for valid URI path text (ANSI). Focuses on RFC 3986 pchar and segment rules.
# It produces a bytes object suitable for FUZZ_PARAM_STR feeding functions that expect
# [first, afterLast) substrings and for uriSetPath* considering host requirements.

UNRESERVED = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
PCHAR_EXTRA = ":@"  # allowed within pchar
PCHAR_SET = UNRESERVED + SUBDELIMS + PCHAR_EXTRA

# Some interesting percent-encodings including space, slash (when encoded), and multitudes
ENCODINGS = [
    "%20", "%2F", "%3A", "%40", "%21", "%7E", "%2b", "%2B", "%25", "%00",
]

# Some reserved but allowed in pchar via pct-encoded; provide hex pairs
HEX = "0123456789ABCDEF"

# Common special segments
SPECIAL_SEGMENTS = [
    "..", ".",  # dot-segments
    "~user",
    "index.html",
    "api",
    "v1",
    "static",
    "images",
    "ä".encode('utf-8', 'ignore').decode('latin1', 'ignore'),  # non-ascii will be filtered later
]

def rand_pct_encoding(rng: random.Random) -> str:
    # Random %HH; include chance of lowercase hex
    a = rng.choice(HEX)
    b = rng.choice(HEX)
    if rng.random() < 0.5:
        a = a.lower()
    if rng.random() < 0.5:
        b = b.lower()
    return f"%{a}{b}"

def rand_pchar(rng: random.Random) -> str:
    r = rng.random()
    if r < 0.15:
        return rand_pct_encoding(rng)
    elif r < 0.85:
        return rng.choice(PCHAR_SET)
    else:
        return rng.choice(ENCODINGS)

def make_segment(rng: random.Random, min_len: int = 0, max_len: int = 16) -> str:
    # Occasionally pick from special segments
    if rng.random() < 0.25 and SPECIAL_SEGMENTS:
        seg = rng.choice(SPECIAL_SEGMENTS)
        # Ensure characters are within 0x01..0x7F or properly percent-encoded
        seg = ''.join(ch for ch in seg if 0x20 <= ord(ch) <= 0x7E)
        if not seg:
            seg = "a"
        return seg
    length = rng.randint(min_len, max_len)
    if length == 0:
        return ""
    return ''.join(rand_pchar(rng) for _ in range(length))

def build_path_abempty(rng: random.Random) -> str:
    # path-abempty: *( "/" segment ) — can be empty or starts with '/'
    segs = []
    count = rng.randint(0, 6)
    for _ in range(count):
        segs.append("/" + make_segment(rng))
    return ''.join(segs)

def build_path_absolute(rng: random.Random) -> str:
    # path-absolute: "/" [ segment-nz *( "/" segment ) ]
    if rng.random() < 0.3:
        # Just root
        return "/"
    segs = ["/" + make_segment(rng, 1, 16)]
    extras = rng.randint(0, 5)
    for _ in range(extras):
        segs.append("/" + make_segment(rng))
    return ''.join(segs)

def build_path_rootless(rng: random.Random) -> str:
    # path-rootless: segment-nz *( "/" segment ) — does not start with '/'
    segs = [make_segment(rng, 1, 16)]
    extras = rng.randint(0, 5)
    for _ in range(extras):
        segs.append("/" + make_segment(rng))
    return ''.join(segs)

def build_path_empty() -> str:
    return ""

def maybe_trailing_slash(path: str, rng: random.Random) -> str:
    if path and rng.random() < 0.2 and not path.endswith('/'):
        return path + "/"
    return path

def inject_interesting_patterns(path: str, rng: random.Random) -> str:
    # Insert sequences like multiple slashes, dot segments, and mixed encodings
    if rng.random() < 0.2:
        path = path.replace("/", "//", 1)
    if rng.random() < 0.2:
        # Insert a dot-segment at random position
        pos = rng.randint(0, len(path))
        insert = "/../" if rng.random() < 0.5 else "/./"
        path = path[:pos] + insert + path[pos:]
    if rng.random() < 0.2:
        # Replace some spaces with %20 (in case any are present later)
        path = path.replace(" ", "%20")
    return path

def ensure_host_compatible(path: str, has_host: bool) -> str:
    # When hasHost is true, non-NULL path must start with '/'
    if has_host:
        if path == "":
            return path
        if not path.startswith('/'):
            return "/" + path
    return path

def choose_style(rng: random.Random) -> str:
    styles = [build_path_abempty, build_path_absolute, build_path_rootless, build_path_empty]
    # Bias toward non-empty but cover all
    weights = [0.35, 0.25, 0.30, 0.10]
    pick = rng.random()
    acc = 0.0
    for w, f in zip(weights, styles):
        acc += w
        if pick <= acc:
            return f.__name__
    return styles[0].__name__

def make_path(rng: random.Random, has_host: bool) -> str:
    style_name = choose_style(rng)
    if style_name == 'build_path_abempty':
        path = build_path_abempty(rng)
    elif style_name == 'build_path_absolute':
        path = build_path_absolute(rng)
    elif style_name == 'build_path_rootless':
        path = build_path_rootless(rng)
    else:
        path = build_path_empty()

    path = maybe_trailing_slash(path, rng)
    path = inject_interesting_patterns(path, rng)
    path = ensure_host_compatible(path, has_host)

    # Clamp size to 1024 like the stub, but keep overall <=4096
    if len(path) > 1024:
        path = path[:1024]
    return path

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomize hasHost like the fuzzer does
    has_host = bool(rng.getrandbits(1))

    # 1/3 chance to return NULL-equivalent empty buffer (stub can pass NULL by making s empty)
    if rng.randrange(3) == 0:
        return b""  # causes first/afterLast to be nullptr in uriIsWellFormedPathA stub

    path = make_path(rng, has_host)

    # Ensure ANSI narrow: keep bytes 0x20..0x7E; other bytes percent-encode
    out_chars: List[str] = []
    for ch in path:
        code = ord(ch)
        if 0x20 <= code <= 0x7E and ch != '%':
            out_chars.append(ch)
        elif ch == '%':
            # Keep percent as part of encodings; ensure next two are hex if not already
            out_chars.append('%')
        else:
            # Percent-encode
            out_chars.append('%{:02X}'.format(code & 0xFF))

    final = ''.join(out_chars)

    # Final clamp to 4096 bytes as per guidance
    if len(final) > 4096:
        final = final[:4096]

    return final.encode('ascii', 'ignore')

import random
import string
from typing import List, Tuple

# Generator for valid URI query text (no leading '?'), intended to be consumed
# as bytes then mapped to wchar_t by the fuzzer (each byte -> wchar with same value).
# We aim to cover:
# - empty queries
# - simple k=v pairs joined by '&' and ';'
# - percent-encodings
# - plus-as-space scenarios (even though well-formedness need not interpret it)
# - RFC3986 unreserved and sub-delims
# - UTF-8-like bytes in 0x80..0xFF range (become wchar_t of same code unit in stub)
# - edge cases: long values, repeated keys, empty value, key without value
# - line breaks and their percent-encoded forms
# - mixtures that should still be well-formed per RFC character classes

UNRESERVED = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
PCT_HEX = string.hexdigits.lower()

# Allowed pchar without pct-encoding in query (RFC 3986): unreserved / pct-encoded / sub-delims / ':' / '@' / '/' / '?'
ALLOWED_QUERY_CHARS = set(UNRESERVED + SUBDELIMS + ":@/?")

# Some interesting raw bytes that are still safe (will be percent-encoded by us when needed)
RAW_SPACES = [" ", "\t"]
LINE_BREAKS = ["\n", "\r", "\r\n"]

def _rand(r: random.Random, seq: List[str]):
    return seq[r.randrange(len(seq))]

def pct_encode_byte(b: int) -> str:
    return "%" + format(b, "02X")

def make_token(r: random.Random, min_len: int, max_len: int, allow_pct: bool = True) -> str:
    n = r.randint(min_len, max_len)
    s = []
    for _ in range(n):
        choice = r.random()
        if choice < 0.60:
            s.append(r.choice(tuple(ALLOWED_QUERY_CHARS)))
        elif choice < 0.80 and allow_pct:
            # percent-encode either an allowed char or a spicy byte
            if r.random() < 0.5:
                b = r.randrange(0, 256)
            else:
                b = ord(r.choice(tuple(ALLOWED_QUERY_CHARS)))
            s.append(pct_encode_byte(b))
        elif choice < 0.90:
            # include plus sign frequently
            s.append("+")
        else:
            # include a space-like or line break sometimes percent-encoded to remain well-formed
            if r.random() < 0.5:
                s.append(_rand(r, RAW_SPACES))
            else:
                lb = _rand(r, LINE_BREAKS)
                # encode line breaks for well-formedness robustness
                s.append("".join(pct_encode_byte(ord(c)) for c in lb))
    return "".join(s)

def make_pair(r: random.Random) -> str:
    key = make_token(r, 0, r.randint(3, 12))
    # occasionally empty value, or missing '=' entirely
    mode = r.randrange(4)
    if mode == 0:
        # key only
        return key
    elif mode == 1:
        # key=
        return key + "="
    else:
        val = make_token(r, 0, r.randint(3, 20))
        return key + "=" + val

def make_query(r: random.Random) -> str:
    # Choose structure
    kind = r.randrange(8)
    if kind == 0:
        return ""  # empty query
    elif kind == 1:
        # single pair
        return make_pair(r)
    elif kind == 2:
        # multiple with '&'
        count = r.randint(2, 8)
        return "&".join(make_pair(r) for _ in range(count))
    elif kind == 3:
        # multiple with ';'
        count = r.randint(2, 8)
        return ";".join(make_pair(r) for _ in range(count))
    elif kind == 4:
        # mix of '&' and ';'
        count = r.randint(3, 10)
        parts = [make_pair(r) for _ in range(count)]
        sep = ["&", ";"]
        out = []
        for i, p in enumerate(parts):
            if i:
                out.append(r.choice(sep))
            out.append(p)
        return "".join(out)
    elif kind == 5:
        # path-like content in query
        segs = [make_token(r, 1, 6) for _ in range(r.randint(2, 6))]
        tail = ("?" + make_token(r, 0, 6)) if r.random() < 0.4 else ""
        return "/".join(segs) + tail
    elif kind == 6:
        # heavy percent-encodings, including high bytes
        n = r.randint(5, 60)
        return "".join(pct_encode_byte(r.randrange(0, 256)) if r.random() < 0.8 else r.choice(tuple(ALLOWED_QUERY_CHARS)) for _ in range(n))
    else:
        # include explicit line breaks and spaces, mostly percent-encoded
        parts = []
        for _ in range(r.randint(2, 6)):
            parts.append(make_token(r, 0, 10))
            if r.random() < 0.7:
                parts.append(pct_encode_byte(0x0D) + pct_encode_byte(0x0A))
            else:
                parts.append("+")
        return "".join(parts).strip("&;")

def clamp_size(b: bytes, max_len: int = 1024) -> bytes:
    if len(b) > max_len:
        return b[:max_len]
    return b

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    q = make_query(r)
    # Convert to bytes. Since the fuzzer maps each byte to a wchar_t with same value,
    # we should emit single-byte encodings. Use latin-1 to preserve 0x00..0xFF mapping.
    data = q.encode('latin-1', errors='ignore')
    # Occasionally generate an empty buffer (valid for useNull=false path too because stub uses first=afterLast)
    if r.random() < 0.05:
        data = b""
    # Keep within fuzzer cap
    return clamp_size(data, 1024)
